30	/* Get types from exported APIs.
31	 * PropertyDecl is not yet handled.
32	 * Abstract function declarations coverage is not yet handled.
33	 * Varargs types are not yet handled.
34	 */
35	class ApiTypeExtractor(component: ComponentIndex,
36	                       globalEnv: GlobalEnvironment) extends Walker {
37	
38	  var exports = Map[APIName, ApiIndex]()
39	  var inTraitOrObject: Option[IdOrOpOrAnonymousName] = None
40	
41	  def check() = {
42	    for ( api <- toSet(component.exports) ) {
43	      exports += ((api, globalEnv.api(api)))
44	    }
45	    walk(component.ast)
46	  }
47	
48	  val errors = new ArrayList[StaticError]()
49	  def getErrors() = errors
50	  private def error(s:String, n:Node) = errors.add(TypeError.make(s,n))
51	
52	  private def isExported(o: TraitObjectDecl): Option[(APIName, Type)] = {
53	    val name = NodeUtil.getName(o)
54	    for ( api <- exports.keySet ) {
55	      val typeConses = exports.get(api).get.typeConses
56	      if ( typeConses.keySet.contains(name) &&
57	           NodeUtil.isObject(typeConses.get(name)) ) {
58	        val od = typeConses.get(name).ast.asInstanceOf[ObjectDecl]
59	        toOption(NodeUtil.getParams(od)) match {
60	          case Some(_) => return Some((api, NodeUtil.getParamType(od).unwrap))
61	          case _ =>
62	        }
63	      }
64	    }
65	    None
66	  }
67	
68	  private def isExported(f: FnDecl, isMethod: Option[IdOrOpOrAnonymousName]): Option[(APIName, Type, Type)] = {
69	    def reportFnDecl(api: APIName, fd: FnDecl) = {
70	      Some((api, NodeUtil.getParamType(fd), NodeUtil.getReturnType(fd).unwrap))
71	    }
72	    def reportLValue(api: APIName, lvalue: LValue) = {
73	      val typeInAPI = lvalue.getIdType.unwrap.asInstanceOf[ArrowType]
74	      Some((api, typeInAPI.getDomain, typeInAPI.getRange))
75	    }
76	    val name = NodeUtil.getName(f)
77	    if ( isMethod.isDefined ) {
78	      val owner = isMethod.get
79	      for ( api <- exports.keySet ) {
80	        val typeConses = exports.get(api).get.typeConses
81	        if ( typeConses.keySet.contains(owner) &&
82	             NodeUtil.isTraitOrObject(typeConses.get(owner)) ) {
83	          val tindex = typeConses.get(owner).asInstanceOf[TraitIndex]
84	          if ( tindex.getters.keySet.contains(name) ) {
85	            return reportFnDecl(api, tindex.getters.get(name).fnDecl.get)
86	          }
87	          if ( tindex.setters.keySet.contains(name) ) {
88	            return reportFnDecl(api, tindex.setters.get(name).fnDecl.get)
89	          }
90	          if ( tindex.dottedMethods.firstSet.contains(name) )
91	            for ( g <- toSet(tindex.dottedMethods.matchFirst(name)) ) {
92	              g match {
93	                case SDeclaredMethod(fd,_) => return reportFnDecl(api, fd)
94	                case _ =>
95	              }
96	            }
97	          if ( tindex.functionalMethods.firstSet.contains(name) )
98	            for ( g <- toSet(tindex.functionalMethods.matchFirst(name)) ) {
99	              g match {
100	                case SFunctionalMethod(fd,_) => return reportFnDecl(api, fd)
101	                case _ =>
102	              }
103	            }
104	          if ( NodeUtil.isObject(typeConses.get(owner)) &&
105	               typeConses.get(owner).asInstanceOf[ObjectTraitIndex].fields.keySet.contains(name) )
106	            typeConses.get(owner).asInstanceOf[ObjectTraitIndex].fields.get(name) match {
107	              case SDeclaredVariable(lvalue) => return reportLValue(api, lvalue)
108	              case _ =>
109	            }
110	        }
111	      }
112	    } else {
113	      for ( api <- exports.keySet ) {
114	        val functions = exports.get(api).get.functions
115	        val variables = exports.get(api).get.variables
116	        if ( functions.firstSet.contains(name) )
117	          for ( g <- toSet(functions.matchFirst(name)) ) {
118	            g match {
119	              case SDeclaredFunction(fd) => return reportFnDecl(api, fd)
120	              case _ =>
121	            }
122	          }
123	        // Check abstract function declarations of the form of variable declarations
124	        if ( variables.keySet.contains(name) )
125	          variables.get(name) match {
126	            case SDeclaredVariable(lvalue) => return reportLValue(api, lvalue)
127	            case _ =>
128	          }
129	      }
130	    }
131	    None
132	  }
133	
134	  private def forParams(params: List[Param], paramTypeInAPI: Type) =
135	    params.length match {
136	      case 0 => params
137	      case 1 => List(forParam((params.head, paramTypeInAPI)))
138	      case _ =>
139	        params.zip(toListFromImmutable(paramTypeInAPI.asInstanceOf[TupleType].getElements)).map(forParam)
140	    }
141	
142	  private def forParam(pair:(Param, Type)) = pair._1 match {
143	    case SParam(info, name, mods, ty, exp, varargsTy) =>
144	      val newTy = ty match {
145	        case Some(_) => ty
146	        case None => Some(pair._2)
147	      }
148	      // Varargs type is not yet handled...
149	      SParam(info, name, mods, newTy, exp, varargsTy)
150	    case p => p
151	  }
152	
153	  private def forLValue(v: LValue, isField: Option[IdOrOpOrAnonymousName]): LValue = v match {
154	    case SLValue(info, name, mods, ty, mutable) =>
155	      if ( ty.isNone ) {
156	        if ( isField.isDefined ) {
157	          val owner = isField.get
158	          for ( api <- exports.keySet ) {
159	            val typeConses = exports.get(api).get.typeConses
160	            if ( typeConses.keySet.contains(owner) &&
161	                 NodeUtil.isObject(typeConses.get(owner)) ) {
162	              val tindex = typeConses.get(owner).asInstanceOf[ObjectTraitIndex]
163	              if ( tindex.fields.keySet.contains(name) )
164	                tindex.fields.get(name) match {
165	                  case SDeclaredVariable(lvalue) =>
166	                    return SLValue(info, name, mods, lvalue.getIdType, mutable)
167	                }
168	            }
169	          }
170	          v
171	        } else {
172	          for ( api <- exports.keySet ) {
173	            val variables = exports.get(api).get.variables
174	            if ( variables.keySet.contains(name) )
175	              variables.get(name) match {
176	                case SDeclaredVariable(vInAPI) =>
177	                  return SLValue(info, name, mods, vInAPI.getIdType, mutable)
178	              }
179	          }
180	          v
181	        }
182	      } else v
183	    case _ => v
184	  }
185	
186	  private def paramWithoutType(p: Param) =
187	    p.getIdType.isNone && p.getVarargsType.isNone
188	
189	  override def walk(node:Any):Any = {
190	    node match {
191	      case t@STraitDecl(info,
192	                        STraitTypeHeader(sparams, mods, name, where,
193	                                         throwsC, contract, extendsC, params, decls),
194	                        self, excludes, comprises, ellipses) =>
195	        inTraitOrObject = Some(name)
196	        val newParams =
197	          if ( params.isSome && params.unwrap.exists(paramWithoutType) )
198	            isExported(t) match {
199	              // If this object o is exported by an API api
200	              case Some((api, paramTypeInAPI)) =>
201	                Some(forParams(params.unwrap, paramTypeInAPI))
202	              case _ => params
203	            }
204	          else params
205	        val newHeader = STraitTypeHeader(sparams, mods, name, where,
206	                                         throwsC, contract, extendsC, newParams,
207	                                         walk(decls).asInstanceOf[List[Decl]])
208	        inTraitOrObject = None
209	        STraitDecl(info, newHeader, self, excludes, comprises, ellipses)
210	
211	      case o@SObjectDecl(info,
212	                         STraitTypeHeader(sparams, mods, name, where,
213	                                          throwsC, contract, extendsC, params, decls),
214	                         self) =>
215	        inTraitOrObject = Some(name)
216	        val newParams =
217	          if ( params.isSome && params.unwrap.exists(paramWithoutType) )
218	            isExported(o) match {
219	              // If this object o is exported by an API api
220	              case Some((api, paramTypeInAPI)) =>
221	                Some(forParams(params.unwrap, paramTypeInAPI))
222	              case _ => params
223	            }
224	          else params
225	        val newHeader = STraitTypeHeader(sparams, mods, name, where,
226	                                         throwsC, contract, extendsC, newParams,
227	                                         walk(decls).asInstanceOf[List[Decl]])
228	        inTraitOrObject = None
229	        SObjectDecl(info, newHeader, self)
230	
231	      case f@SFnDecl(info,
232	                     SFnHeader(sparams, mods, name, where,
233	                               throwsC, contract, params, returnType),
234	                     unambiguousName, body, impName) =>
235	        if ( NodeUtil.getReturnType(f).isNone ||
236	             toListFromImmutable(NodeUtil.getParams(f)).exists(paramWithoutType) ) {
237	          isExported(f, inTraitOrObject) match {
238	            // If this function f is exported by an API api
239	            case Some((api, paramTypeInAPI, returnTypeInAPI)) =>
240	              val newReturnType = returnType match {
241	                case Some(_) => returnType
242	                // and f does not have a return type annotation,
243	                // get the type from the API api
244	                case _ => Some(returnTypeInAPI)
245	              }
246	              SFnDecl(info,
247	                      SFnHeader(sparams, mods, name, where, throwsC, contract,
248	                                forParams(params, paramTypeInAPI), newReturnType),
249	                      unambiguousName, body, impName)
250	            case _ => f
251	          }
252	        } else f
253	
254	      case v@SVarDecl(info, lhs, body) =>
255	        SVarDecl(info, lhs.map(forLValue(_, inTraitOrObject)), body)
256	
257	      case _ => super.walk(node)
258	    }
259	  }
260	}
261

    }

    /* A declaration's parameter types without self, as the trait or object being checked
     * has them, over the method's own static parameters renamed apart (ownStaticParamsApart):
     * what STypesUtil.providedMethods compares. */
    private def paramsWithoutSelf(d: (JavaFunctional, StaticTypeReplacer, TraitType)): Option[Type] = d match {
      case (f, replacer, _) =>
        val ps = toListFromImmutable(f.parameters)
        val kept = f match {
          case m: JavaFunctionalMethod => ps.zipWithIndex.filter(_._2 != m.selfPosition).map(_._1)
          case _ => ps }
        STypesUtil.paramsToType(kept, f.getSpan).map { t =>
          val (sparams, apart) = ownStaticParamsApart(f)
          replacer.replaceIn(insertStaticParams(apart(t), sparams)) }
    }

    // for dotted methods
    private def toMethodArrows(set: Set[(JavaFunctional, StaticTypeReplacer, TraitType)])
                           : List[(ArrowType,Option[Int],Option[JavaFunctional])] =
      set.filter(p => p match { case (f, _, _) => isDeclaredMethod(f)})
         .toList.map(p => p match { case (f, replacer, _) =>
              val (sparams, apart) = ownStaticParamsApart(f)
              (NF.makeArrowType(f.getSpan,
	                        replacer.replaceIn(apart(paramsToType(f.asInstanceOf[JavaMethod].selfType.unwrap, f.parameters, f.getSpan))),
                		replacer.replaceIn(apart(f.getReturnType.unwrap)),
				sparams),
               None,
	       Some(f))})

    /* An inherited method's own static parameters, each whose name is a static parameter
     * of the trait or object being checked renamed apart, so that the arguments the
     * replacer puts in place of the declaring trait's parameters are not captured. */
    private def ownStaticParamsApart(f: JavaFunctional): (JavaList[StaticParam], Type => Type) = {
      val own = toListFromImmutable(getStaticParameters(f, false))
      val env = typeAnalyzer.env
      val taken = own.map(_.getName.getText).toSet
      val clash = own.filter(p => env.contains(p.getName))
      if (clash.isEmpty) return (getStaticParameters(f, false), (t: Type) => t)
      val subst: List[(IdOrOp, IdOrOp)] = clash.map { p =>
        val n = p.getName
        val fresh = Iterator.from(1).map(i => NF.makeId(NU.getSpan(n), n.getText + "$" + i))
                            .find(m => !env.contains(m) && !taken.contains(m.getText)).get
        (n, fresh) }
      def apart(t: Type): Type = alphaRename(subst, t).asInstanceOf[Type]
      // every own parameter's bounds are renamed, so that a bound naming a renamed parameter names it still
      val renamed = own.map(p => {
        def bounds = toJavaList(toListFromImmutable(p.getExtendsClause).map(b => alphaRename(subst, b).asInstanceOf[BaseType]))
        subst.find(_._1 == p.getName) match {
          case Some((_, m)) => NF.makeStaticParam(p, m.asInstanceOf[Id], bounds)
          case None => p.getName match {
            case n: Id if !p.getExtendsClause.isEmpty => NF.makeStaticParam(p, n, bounds)
            case _ => p }
        } })
      (toJavaList(renamed), apart)
    }


    /* Called by com.sun.fortress.compiler.StaticChecker.checkComponent
     *       and com.sun.fortress.compiler.StaticChecker.checkApi
     */
    def checkOverloading(): JavaList[StaticError] = {
        val fnsInComp = compilation_unit.functions
        val functions = fnsInComp.firstSet
        val ast = compilation_unit.ast
        val kindAndName = (compilation_unit match { case _:ComponentIndex => "component "; case _:ApiIndex => "API " }) + compilation_unit.name
        val importItems = toListFromImmutable(ast.getImports)
        val importStars = importItems.filter(_.isInstanceOf[ImportStar]).map(_.asInstanceOf[ImportStar])
        val importNames = importItems.filter(_.isInstanceOf[ImportNames]).map(_.asInstanceOf[ImportNames])

        // First check names of functions declared in this component.
        for ( f <- toSet(functions) ; if isDeclaredName(f) ) {
          val name = f.asInstanceOf[IdOrOp].getText
          var set = getFunctionsFromCompilationUnit(compilation_unit, f)

          for ( i <- importNames ) {
            for ( n <- toListFromImmutable(i.getAliasedNames) ) {
              if ( n.getAlias.isSome &&
                   n.getAlias.unwrap.asInstanceOf[IdOrOp].getText.equals(name) ) {
                // get the JavaFunctionals from the api and add them to set
                set ++= getFunctions(globalEnv.lookup(i.getApiName), n.getName)
              } else if ( n.getAlias.isNone &&
                          n.getName.asInstanceOf[IdOrOp].getText.equals(name) ) {
                // get the JavaFunctionals from the api and add them to set
                set ++= getFunctions(globalEnv.lookup(i.getApiName), f)
              }
            }
          }

          for ( i <- importStars ) {
            val index = globalEnv.lookup(i.getApiName)
            val excepts = toListFromImmutable(i.getExceptNames).asInstanceOf[List[IdOrOp]]
            for ( n <- toSet(index.functions.firstSet).++(toSet(index.variables.keySet)) ) {
              val text = n.asInstanceOf[IdOrOp].getText
              if ( text.equals(name) &&
                   ! excepts.contains((m:IdOrOp) => m.getText.equals(text)) ) {
                // get the JavaFunctionals from the api and add them to set
                set ++= getFunctions(index, f)
              }
            }
          }

          // debugging probe: TypeError.b3(name, f, set)
          checkFunctionOverloading(kindAndName, f, set, globalOracle)

          val dFunctions = getDeclaredFunctions(compilation_unit, f)

          var fMethods = getFunctionalMethods(compilation_unit, f)

          for ( i <- importNames ) {
            for ( n <- toListFromImmutable(i.getAliasedNames) ) {
              if ( n.getAlias.isSome &&
                   n.getAlias.unwrap.asInstanceOf[IdOrOp].getText.equals(name) ) {
                // get the JavaFunctionals from the api and add them to set
                fMethods ++= getFunctionalMethods(globalEnv.lookup(i.getApiName), n.getName)
              } else if ( n.getAlias.isNone &&
                          n.getName.asInstanceOf[IdOrOp].getText.equals(name) ) {
                // get the JavaFunctionals from the api and add them to set
                fMethods ++= getFunctionalMethods(globalEnv.lookup(i.getApiName), f)
              }
            }
          }

          for ( i <- importStars ) {
            val index = globalEnv.lookup(i.getApiName)
            val excepts = toListFromImmutable(i.getExceptNames).asInstanceOf[List[IdOrOp]]
            for ( n <- toSet(index.functions.firstSet).++(toSet(index.variables.keySet)) ) {
              val text = n.asInstanceOf[IdOrOp].getText
              if ( text.equals(name) &&
                   ! excepts.contains((m:IdOrOp) => m.getText.equals(text)) ) {
                // get the JavaFunctionals from the api and add them to set
                fMethods ++= getFunctionalMethods(index, f)
              }
            }
          }          

          checkFancyRule(f, dFunctions, fMethods, globalOracle)

        }

        // Overloading checking for imported functionals that are not declared in this component
        for ( f <- importNames ) {
          for ( g <- toListFromImmutable(f.getAliasedNames);
                if (g.getAlias.isSome && ! toSet(functions).contains(g.getAlias.unwrap)) ||
                   ! toSet(functions).contains(g.getName) ) {
            val name = if (g.getAlias.isSome) g.getAlias.unwrap.asInstanceOf[IdOrOp].getText
                       else g.getName.asInstanceOf[IdOrOp].getText
            var set = getFunctions(globalEnv.lookup(f.getApiName), g.getName)
            for ( i <- importNames ; if ! f.getApiName.getText.equals(i.getApiName.getText)) {
              for ( n <- toListFromImmutable(i.getAliasedNames) ) {
                if ( n.getAlias.isSome &&
                     n.getAlias.unwrap.asInstanceOf[IdOrOp].getText.equals(name) ) {
                  // get the JavaFunctionals from the api and add them to set
                  set ++= getFunctions(globalEnv.lookup(i.getApiName), n.getName)
                } else if ( n.getAlias.isNone &&
                            n.getName.asInstanceOf[IdOrOp].getText.equals(name) ) {
                  // get the JavaFunctionals from the api and add them to set
                  set ++= getFunctions(globalEnv.lookup(i.getApiName), g.getName)
                }
              }
            }
            for ( i <- importStars ) {
              val index = globalEnv.lookup(i.getApiName)
              val excepts = toListFromImmutable(i.getExceptNames).asInstanceOf[List[IdOrOp]]
              for ( n <- toSet(index.functions.firstSet).++(toSet(index.variables.keySet)) ) {
                val text = n.asInstanceOf[IdOrOp].getText
                if ( text.equals(name) &&
                     ! excepts.contains((m:IdOrOp) => m.getText.equals(text)) ) {
                  // get the JavaFunctionals from the api and add them to set
                  set ++= getFunctions(index, g.getName)
                }
              }
            }
            checkFunctionOverloading(kindAndName, g.getName, set, globalOracle)
          }
        }

        // All inherited abstract methods in objects should have implementations.
        if ( compilation_unit.isInstanceOf[ComponentIndex] )
          errors = errors ::: new AbstractMethodChecker(compilation_unit.asInstanceOf[ComponentIndex],
                                                        globalEnv).check()

        // Now check trait and object declarations.
        val typesInComp = compilation_unit.typeConses
        for ( t <- toSet(typesInComp.keySet) ; if NU.isTraitOrObject(typesInComp.get(t)) ) {
            val traitOrObject = typesInComp.get(t).asInstanceOf[TraitIndex]
            val traitKindAndName = (compilation_unit match { case _:ObjectTraitIndex => "object "; case _ => "trait " }) + NU.getName(traitOrObject.ast)
            // Extend the type analyzer with the collected static parameters
            val oldTypeAnalyzer = typeAnalyzer
            // Add static parameters of the enclosing trait or object
            typeAnalyzer = typeAnalyzer.extend(toListFromImmutable(traitOrObject.staticParameters),
                                               None)
            staticParamsInScope = toListFromImmutable(traitOrObject.staticParameters)
            val oracle = new OverloadingOracle()(typeAnalyzer)
            /* The parameter type of a setter must be the same as the return type
             * of a getter with the same name, if any.
             */
            for ( f <- toSet(traitOrObject.setters.keySet) ) {
                if ( traitOrObject.getters.keySet.contains(f) ) {
                    val getter = traitOrObject.getters.get(f)
                    // Setter declarations are guaranteed to have a single parameter.
                    val param = traitOrObject.setters.get(f).parameters.get(0)
                    val span = getter.getSpan
                    if ( param.getIdType.isSome ) {
                        if (! isTrue(typeAnalyzer.equivalent(NU.optTypeOrPatternToType(param.getIdType).unwrap,
                                                      getter.getReturnType.unwrap))(typeAnalyzer) )
                            error(span,
                                  "The parameter type of a setter must be " +
                                  "the same as\n    the return type of a getter " +
                                  "with the same name, if any.")
                    }
                }
            }

            val tt = STypesUtil.declToTraitType(traitOrObject.ast)
	        // the methods the trait or object provides, by the traits chapter's inheritance
	        val (methodsR, overridden) = providedAndOverridden(tt, allMethods(tt, typeAnalyzer), typeAnalyzer, paramsWithoutSelf)

	        for (f <- toSet(methodsR.firstSet) ; if isDeclaredName(f) ) {
                  val mset = toSet(methodsR.matchFirst(f))
	              val dottedMethods = mset.filter(x => x match { case (m, str, tt) => m.isInstanceOf[JavaMethod] &&
	      	      		  		     	     	      m.asInstanceOf[JavaMethod].selfType.isSome })  // unsure why this second condition
	              checkMethodOverloading(traitKindAndName, f, toMethodArrows(dottedMethods), oracle)
	              val functionalMethods = mset.filter(x => x match { case (m, str, tt) => m.isInstanceOf[JavaFunction]})
	              checkMethodOverloading(traitKindAndName, f, toFunctionalMethodArrows(functionalMethods, oracle), oracle)
	        }
	        // a declaration and one it keeps from being inherited: their return types
	        for ((f, o, p, equal) <- overridden ; if isDeclaredName(f))
	          checkOverridingReturnType(f, o, p, equal, oracle)
            typeAnalyzer = oldTypeAnalyzer
            staticParamsInScope = Nil
        }
        toJavaList(errors)
    }

    private def checkFancyRule(name: IdOrOpOrAnonymousName,
    	    		       dFunctions: List[(ArrowType,Option[Int],Option[JavaFunctional])],
			       fMethods: List[(ArrowType,Option[Int],Option[JavaFunctional])],
			       oracle: OverloadingOracle) = {
      // These variables are used to improve the error message
      var x: ArrowType = null 
      var y: ArrowType = null  
      if (!dFunctions.forall(f => fMethods.forall( m => if (!(oracle.lteq(f._1,m._1))) true else { x = f._1; y = m._1; false } )))
        error(x.getInfo().getSpan(),"Overload violation: the declaration of top-level function " + name + " on line " + 
             x.getInfo().getSpan() + " is more specific than the declaration of the functional method " + name + " on line " + 
             y.getInfo().getSpan())
    }

    /* Checks the validity of the overloaded method declarations. */
    private def checkMethodOverloading(containingKindAndName: String,
    	    			       name: IdOrOpOrAnonymousName,
                                       triples: List[(ArrowType,Option[Int],Option[JavaFunctional])],
				       oracle: OverloadingOracle)
                                      : Unit =
      checkOverloading(containingKindAndName, name, triples, true, oracle)

    /* Checks the validity of the overloaded function declarations. */
    private def checkFunctionOverloading(containingKindAndName: String,
    	    			         name: IdOrOpOrAnonymousName,
                                         triples: List[(ArrowType,Option[Int],Option[JavaFunctional])],
					 oracle: OverloadingOracle)
                                        : Unit =
      checkOverloading(containingKindAndName, name, triples, false, oracle)

    /* Checks the validity of the overloaded function declarations. */
    private def checkOverloading(containingKindAndName: String,
    	    			 name: IdOrOpOrAnonymousName,
                                 triples: List[(ArrowType,Option[Int],Option[JavaFunctional])],
                                 isMethod: Boolean,
				 oracle: OverloadingOracle)
                                : Unit = 
        triples.size match {
