case class Disjuncts(es: Set[Conjuncts]) extends EFormula {}

object Formula{

  private val tUnit = TPrimitive(Set(), Set(), Set(), Set(), Set(), Set())
  private val oUnit = OPrimitive(Set(),Set())
  private val nUnit = NPrimitive(Set(),Set())
  val oEmptySub = oSubstitution(Map()) 
  val tEmptySub = tSubstitution(Map())
  val nEmptySub = nSubstitution(Map())
  private def oEq(a: Op, b: Op) = a==b

  def tSubstitution(tmap: Map[_InferenceVarType, Type]): Type => Type = TU.liftSubstitution(tmap)
  def oSubstitution(omap: Map[_InferenceVarOp, Op]): Op => Op = TU.liftSubstitution(omap)
  def nSubstitution(nmap: Map[_InferenceVarInt, IntExpr]): IntExpr => IntExpr = TU.liftSubstitution(nmap)
  def insertOps(omap: Op => Op): Type => Type = TU.liftSubstitution[Op, Op, Type]{case x:Op => omap(x)}
  def insertNats(nmap: IntExpr => IntExpr): Type => Type =
    TU.liftSubstitution[IntExpr, _InferenceVarInt, Type]{case x:_InferenceVarInt => nmap(x)}

  /* A size with each operation whose operands are numerals computed: 2 3 is
   * 6, s0 s1 stays s0 s1.  The run time computes the same operations
   * (Naming.sizeOp); an operation it does not compute is kept as written.
   */
  def foldSize(e: IntExpr): IntExpr = e match {
    case b@SIntBinaryOp(info, paren, l, r, op) =>
      (foldSize(l), foldSize(r)) match {
        case (x: IntBase, y: IntBase) =>
          val v = com.sun.fortress.runtimeSystem.Naming.sizeOp(op.getText, x.getIntVal.getIntVal, y.getIntVal.getIntVal)
          if (v == null) SIntBinaryOp(info, paren, x, y, op)
          else NodeFactory.makeIntBase(NodeUtil.getSpan(b), paren,
                 com.sun.fortress.nodes_util.ExprFactory.makeIntLiteralExpr(NodeUtil.getSpan(b), v))
        case (x, y) => SIntBinaryOp(info, paren, x, y, op)
      }
    case _ => e
  }

  /* Two sizes are equal when their written forms are, once numerals are
   * folded: the same inference variable, the same static parameter, the same
   * number, or the same operation on equal sizes; s0 s1 is not s1 s0.  The
   * generated equals compares source positions, so it is not used.
   */
  def nEq(a: IntExpr, b: IntExpr): Boolean = sameSize(foldSize(a), foldSize(b))

  private def sameSize(a: IntExpr, b: IntExpr): Boolean = (a, b) match {
    case (x: _InferenceVarInt, y: _InferenceVarInt) => x.getId eq y.getId
    case (x: IntRef, y: IntRef) => x.getName.getText == y.getName.getText
    case (x: IntBase, y: IntBase) => x.getIntVal.getIntVal == y.getIntVal.getIntVal
    case (SIntBinaryOp(_, _, l1, r1, o1), SIntBinaryOp(_, _, l2, r2, o2)) =>
      o1.getText == o2.getText && sameSize(l1, l2) && sameSize(r1, r2)
    case _ => false
  }

  /* Two sizes known to differ: two different numerals, or two different
   * static parameters.  A name or an operation beside a numeral or an
   * operation may be equal to it, as the specification's Q&A on overloaded
   * operators answers (n+1 beside 0); nEq says when it is.
   */
  def nDiffer(a: IntExpr, b: IntExpr): Boolean = (foldSize(a), foldSize(b)) match {
    case (x: IntBase, y: IntBase) => !sameSize(x, y)
    case (x: IntRef, y: IntRef) => !sameSize(x, y) && !isOpenedSize(x) && !isOpenedSize(y)
    case _ => false
  }

  /* A size opened from a value: comprises { N[\n\] } where [\nat n\] lists N
   * at every n, and a value of the trait passed where N[\m\] is expected binds
   * m to its own size, a name no program can write, equal only to itself and
   * not known to differ from any size (TypeAnalyzer.openWhereSizes).
   */
  private val openedSizeMark = "#"
  private val openedSizes = new java.util.concurrent.atomic.AtomicInteger()
  def openedSizeName(where: String): String = where + openedSizeMark + openedSizes.incrementAndGet
  // How many sizes have been opened so far: a computation that opens one is not repeated by a memo.
  def openedSizeCount: Int = openedSizes.get
  def isOpenedSize(e: IntExpr): Boolean = e match {
    case r: IntRef => r.getName.getText.contains(openedSizeMark)
    case _ => false
  }

  // A static parameter or a literal: what a size variable can be bound to
  def isNatTerm(e: IntExpr): Boolean = e.isInstanceOf[IntRef] || e.isInstanceOf[IntBase]

  private def merge[S,T](a: Map[S, T], b: Map[S,T], bin: (T,T) => T, unit: T): Map[S, T] =
    Map((a.keySet ++ b.keySet).map(k =>

  nds.filterNot{c => nds.exists(d => implies(c, d) && !equivalent(c,d))}
}

/* A conjunction or a disjunction is reduced once in each analyzer: asked again, the
 * analyzer answers with its first reduction (TypeAnalyzer.reduced). */
def reduce(c: CFormula)(implicit ta: TypeAnalyzer): CFormula = c match {
  case _: And | _: Or => ta.reduced(c)(reduceOnce(c))
  case _ => c
}

private def reduceOnce(c: CFormula)(implicit ta: TypeAnalyzer): CFormula =  c match {
  case And(ts, os, ns) =>
    def tSimplify(ip: (_InferenceVarType, TPrimitive)): Option[(_InferenceVarType, TPrimitive)] = ip match {
      // catch trivial contradictions 
      case (i, TPrimitive(pl,nl,pu,nu,pe,ne)) 
        if (nl.contains(i) || nu.contains(i) || pe.contains(i) || 
            nl.contains(BOTTOM)|| ne.contains(BOTTOM) || nu.contains(ANY)) =>
          None
      case (i, TPrimitive(pl,nl,pu,nu,pe,ne))
        if (pe.contains(ANY)) =>
          tSimplify(i, TPrimitive(pl, nl, Set(BOTTOM), nu, Set(), ne))
      case (i, TPrimitive(pl,nl,pu,nu,pe,ne)) =>
        Some((i, TPrimitive(maxTypes(pl.filter(_!=i)), minTypes(nl) ++ nl.filter(_==ANY), 
                                    minTypes(pu.filter(_!=i)) , maxTypes(nu) ++ nu.filter(_==BOTTOM), 
                                    maxTypes(pe), minTypes(ne) ++ ne.filter(_==ANY))))
    }
    // Comprises means there are more of these
    def tContradiction(ip: (_InferenceVarType, TPrimitive)) = {
      val TPrimitive(pl,nl,pu,nu,pe,ne) = ip._2
      if(isFalse(ta.subtype(ta.join(pl), ta.meet(pu))) ||
         nl.exists(n => pl.exists(ta.lteq(n, _))) ||
         nu.exists(n => pu.exists(ta.lteq(_, n))) ||
         pe.exists(e => pu.exists(ta.lteq(_,e))) ||
         pl.exists(l => pe.exists(e => isFalse(ta.excludes(l,e)))) ||
         ne.exists(n => pe.exists(ta.lteq(n, _))) ||
         ne.exists(n => pu.exists(ta.definitelyExcludes(n, _))))
        None
      else
        Some(ip)
    }
    def tRedundant(ip: (_InferenceVarType, TPrimitive)) = {
      val TPrimitive(pl,nl,pu,nu,pe,ne) = ip._2
      Some((ip._1, TPrimitive(pl,
                     nl.filterNot(n => pu.exists(p => isFalse(ta.subtype(n, p)))).
                        filterNot(n => pe.exists(ta.definitelyExcludes(n, _))),
                     pu,
                     nu.filterNot(n => pl.exists(p => isFalse(ta.subtype(p, n)))).
                        filterNot(n => pe.exists(ta.definitelyExcludes(n, _))),
                     pe.filterNot(p => pu.exists(ta.definitelyExcludes(p, _))),
                     ne.filterNot(n => pu.exists(ta.lteq(_, n))).
                        filterNot(n => pl.exists(p => isFalse(ta.excludes(p, n)))))))
    }
    def tTrivial(ip: (_InferenceVarType, TPrimitive)) = {
      val TPrimitive(pl,nl,pu,nu,pe,ne) = ip._2
      pl.isEmpty && nl.isEmpty && pu.isEmpty && nu.isEmpty && pe.isEmpty && ne.isEmpty
    }
    def oSimplify(ip: (_InferenceVarOp, OPrimitive)) = {
      val (i, OPrimitive(ps, ns)) = ip
      val sps = removeDups(ps - i, oEq)
      val sns = removeDups(ns, oEq)
      (i, OPrimitive(sps, sns))
    }
    def oContradiction(ip: (_InferenceVarOp, OPrimitive)) = {
      val (i, OPrimitive(ps, ns)) = ip
      if(ns.contains(i) || ps.exists(p => ns.contains(p)) || ps.filterNot(_.isInstanceOf[_InferenceVarOp]).size > 1)
        None
      else
        Some(ip)
    }
    def oTrivial(ip: (_InferenceVarOp, OPrimitive)) = {
      val (i, OPrimitive(ps, ns)) = ip
      ps.isEmpty && ns.isEmpty
    }
    def nSimplify(ip: (_InferenceVarInt, NPrimitive)) = {
      val (i, NPrimitive(ps, ns)) = ip
      (i, NPrimitive(removeDups(ps.filterNot(nEq(i, _)), nEq), removeDups(ns, nEq)))
    }
    // A size variable equal to two different sizes, or to arithmetic, has no solution
    def nContradiction(ip: (_InferenceVarInt, NPrimitive)) = {
      val (i, NPrimitive(ps, ns)) = ip
      if(ns.exists(nEq(i, _)) || ps.exists(p => ns.exists(nEq(p, _))) ||
         ps.exists(p => !isNatTerm(p) && !p.isInstanceOf[_InferenceVarInt]) ||
         removeDups(ps.filterNot(_.isInstanceOf[_InferenceVarInt]), nEq).size > 1)
        None
      else
        Some(ip)
    }
    def nTrivial(ip: (_InferenceVarInt, NPrimitive)) = {
      val (i, NPrimitive(ps, ns)) = ip
      ps.isEmpty && ns.isEmpty
    }
    val nts = ts.map(tSimplify).map(_.flatMap(tContradiction)).map(_.flatMap(tRedundant)).map(_.getOrElse(return False)).filterNot(tTrivial)
    val nos = os.map(oSimplify).map(oContradiction).map(_.getOrElse(return False)).filterNot(oTrivial)
    val nns = ns.map(nSimplify).map(nContradiction).map(_.getOrElse(return False)).filterNot(nTrivial)
    if (nts.isEmpty && nos.isEmpty && nns.isEmpty)
      return True
    else
      And(Map(nts.toSeq: _*), Map(nos.toSeq: _*), Map(nns.toSeq: _*)) 
  case Or(cs) =>
    val rcs = cs.map(reduce(_))
    if(rcs.contains(True))
      True
    else {
      val ncs = maximalCFormulas(rcs)
      ncs.size match {
        case 0 => False
        case 1 => ncs.head
        case _ => Or(ncs.asInstanceOf[Set[And]])
      }
    }
  case _ => c
}

private def minTypes(s: Set[Type])(implicit ta: TypeAnalyzer) =
    TU.conjuncts(ta.meet(s))

private def maxTypes(s: Set[Type])(implicit ta: TypeAnalyzer) =
    TU.disjuncts(ta.join(s))

def reduce(e: EFormula)(implicit ta: TypeAnalyzer): EFormula = e match {
  case Conjuncts(as, os, ms) => 
    val ras = reduce(as, ta.equiv).map{x => removeDups(x, (a: Type, b: Type) => ta.equiv(a, b))}.
      filter{_.size > 1}
    val ros = reduce(os, (a: Op, b: Op) => a==b).map{
      x => removeDups(x, (a: Op, b: Op) => a==b)}.
      filter{_.size > 1}
    val rns = reduce(ms, nEq).map{x => removeDups(x, nEq)}.filter{_.size > 1}
    if(ras.isEmpty && ros.isEmpty && rns.isEmpty)
      True
    else if(isContradictory(ras, (s: Type, t: Type) => isFalse(ta.equivalent(s,t)))
            || isContradictory(ros, definitelyNotEqual)
            || isContradictory(rns, definitelyNotEqualNat))
      False
    else
      Conjuncts(ras, ros, rns)  
  case True => True
  case False => False
  case Disjuncts(es) => 
    val nes = es.map(reduce).filter{_.isInstanceOf[Conjuncts]}
    nes.size match {
      case 0 => False
      case 1 => nes.head
      case _ => Disjuncts(nes.asInstanceOf[Set[Conjuncts]])
    }
}

private def definitelyNotEqual(a: Op, b: Op): Boolean = (a, b) match {
  case (_: _InferenceVarOp, _) => false
  case (_, _:_InferenceVarOp) => false
  case _ => a!=b
}

private def definitelyNotEqualNat(a: IntExpr, b: IntExpr): Boolean = (a, b) match {
  case (_: _InferenceVarInt, _) => false
  case (_, _:_InferenceVarInt) => false
  case _ => nDiffer(a, b)
}

private def isContradictory[T](as: Set[Set[T]], neq: (T,T) => Boolean): Boolean =
  !as.isEmpty && as.forall{a =>  !a.isEmpty && a.tail.foldLeft((a.head, false)){case ((s, b), t) => (t, neq(s,t) || b)}._2}
/*
 * Given a set of sets of Ts that are supposed to represent
 * equivalence classes, this method merges together any classes
 * that share a T to give a reduced set of sets of Ts.
 */

private def reduce[T](es: Set[Set[T]], eq: (T,T)=>Boolean): Set[Set[T]] = {
  def binReduce(e1: Set[T], es: Set[Set[T]]): Set[Set[T]] = 
    if(es.isEmpty)
      Set(e1)
    else {
      // Since es is reduced there will be 0 or 1 matches
      val e2 = es.filter(e => e.exists(a => e1.exists(eq(_, a)))).headOption
      val nes = es.filterNot(e => e.exists(a => e1.exists(eq(_, a))))
      Set(e2.getOrElse(Set()) ++ e1) ++ nes
    }
  es.foldLeft(Set[Set[T]]()){(a, b) => binReduce(b, a)}
}

/*
 * Solves a constraint formula by first unifying away all the equality constraints
 * and then using Dan's simple algorithm from "Java Type Inference is Broken." Dan's
 * algorithm does not do very well when inference variables have bounds that contain
 * other inference variables such as those that arise from the self type idiom. At some
 * point it would be a good idea to replace this with a smarter algorithm.
 */

def solve(c: CFormula)(implicit ta: TypeAnalyzer): Option[(Type => Type, Op => Op, IntExpr => IntExpr)] = 
  slv(reduce(c), false)

/*
 * Solves a constraint formula on the static arguments of a call. A type
 * inference variable that no lower bound fixes takes the intersection of its
 * upper bounds, its declared bound and what the expected type requires, and
 * one the formula leaves unconstrained takes Any; none takes BottomType, and a
 * lower bound BottomType fixes nothing.
 */
def solveToBounds(c: CFormula)(implicit ta: TypeAnalyzer): Option[(Type => Type, Op => Op, IntExpr => IntExpr)] =
  slv(reduce(c), true)

private def slv(c: CFormula, toBounds: Boolean)(implicit ta: TypeAnalyzer): Option[(Type => Type, Op => Op, IntExpr => IntExpr)] = c match {
  // False cannot be solved
  case False => None
  // True has the trivial solution
  case True => Some((if (toBounds) TU.topIvars else tEmptySub, oEmptySub, nEmptySub))
  // We solve an Or by solving one of its branches

  private def slv(c: CFormula, toBounds: Boolean)(implicit ta: TypeAnalyzer): Option[(Type => Type, Op => Op, IntExpr => IntExpr)] = c match {
    // False cannot be solved
    case False => None
    // True has the trivial solution
    case True => Some((if (toBounds) TU.topIvars else tEmptySub, oEmptySub, nEmptySub))
    // We solve an Or by solving one of its branches
    case Or(cs) => 
      for (e <- cs) {
        val se = slv(e, toBounds)
        if(se.isDefined)
          return se
      }
      None
    /* To solve an And:
     * 1) Factor the constraint formula into the conjunction of an equality constraint E
     * and additional constraints I
     * 2) Find the principal unifier U of E
     * 3) Apply U to I to get I'
     * TODO: We can solve more constraints if we iterate 1), 2) 3) until we hit a fixed point but we must be careful to ensure termination
     * 4) Solve I' to get a substitution S
     * 5) Return S composed with U
     */
    case _:And => 
      val (newCon, tUnifier, oUnifier, nUnifier) = unify(c).getOrElse(return None)
      newCon match {
        case True => Some((if (toBounds) TU.topIvars compose tUnifier else tUnifier, oUnifier, nUnifier))
        case False => None
        case nc0@And(ts, os, ns) =>
//	  println("nc: " + nc0)
          // Operators only have equality constraints so they should always be solved by unification
          assert(os.isEmpty)
          // So do sizes: an equality left over has no solution, and a size
          // with only disequalities left is left unsolved
          if (ns.exists{case (_, NPrimitive(pe, _)) => !pe.isEmpty}) return None
          val nc = And(ts, os)
          def boundOnly(p: TPrimitive) =
            toBounds && p.pl.forall(l => TU.hasInferenceVars(l) || l.isInstanceOf[BottomType])
          val lowered = ts.filterNot(e => boundOnly(e._2)).map{
              case (k, p@TPrimitive(pl,nl,pu,nu,pe,ne)) => {
                var uni = ta.join(pl.filterNot(TU.hasInferenceVars))
                // Heuristic extension to Dan Smith's algorithm:
                // If there is a single lower bound and it is a trait type, 
                // try all of its ancestors, searching for one that satisfies
                // all upper bounds.
//		println("uni: " + uni)
//		println("pl: " + pl)
                if (pl.size == 1) {
                  pl.head match {
                    case tt:TraitType =>
                      for (a <- (ta.ancestors(tt) ++ List(uni)).toList.sortWith((a,b) => isTrue(ta.subtype(b,a)))) {
		        val proposedMap = cMap(nc, TU.killIvars compose tSubstitution(Map((k,p)).map(_=>(k,a))))
//			println("For ancestor " + a + " proposed map is " + proposedMap)
                        if (isTrue(proposedMap)) {
                          uni = a 
                        }
                      }
                    case _ => 0
                  }
                }
//                println("slv: new (k->uni) = " + k + "->" + uni)
                (k, uni)
              }
            }.toMap
          // A variable that no lower bound fixes takes the meet of its upper bounds, each
          // at the solutions of the other variables it mentions once those are found, as a
          // bound that mentions another static parameter is taken at that parameter's
          // instance; a bound that still mentions a variable, the variable itself among
          // them, is left out.
          var solved: Map[_InferenceVarType, Type] = lowered
          var pending = ts.toList.filter(e => boundOnly(e._2))
          def waits(k: _InferenceVarType, p: TPrimitive) =
            p.pu.exists(u => TU.getInferenceVars(tSubstitution(solved)(u)).exists(v => v != k && pending.exists(_._1 == v)))
          var ready = pending.filterNot(e => waits(e._1, e._2))
          while (ready.nonEmpty || pending.nonEmpty) {
            val now = if (ready.nonEmpty) ready else pending
            val known = tSubstitution(solved)
            for ((k, p) <- now) {
              val upper = ta.meet(p.pu.map(known).filterNot(TU.hasInferenceVars))
              if (upper.isInstanceOf[BottomType]) return None
              solved = solved + (k -> upper)
            }
            pending = pending.filterNot(e => now.exists(_._1 == e._1))
            ready = pending.filterNot(e => waits(e._1, e._2))
          }
          val sub = (if (toBounds) TU.topIvars else TU.killIvars) compose tSubstitution(solved)
	  val newMap = cMap(nc, sub)
//	  println("newMap: " + newMap)
          if(isTrue(newMap))
            Some((sub compose tUnifier, oUnifier, nUnifier))
          else {
//               println("sub:" + sub + " on formula " + c)
               None
          }
        // Should never occur
        case _:Or => bug("Applied a substitution to an And and got an Or")
      }      
  }

  def unify(c: CFormula)(implicit ta: TypeAnalyzer): Option[(CFormula, Type => Type, Op => Op, IntExpr => IntExpr)] = {
      val eq = getEquality(c)
//      println("Unify " + c + " produces " + eq)
      un(eq).map{case (ts, os, ns) => (cMap(c, ts, os, ns), ts, os, ns)}
  }

  def unifyWithDebug(c: CFormula, debug:Boolean=false)(implicit ta: TypeAnalyzer): Option[(CFormula, Type => Type, Op => Op, IntExpr => IntExpr)] = {
      val eq = getEquality(c)
      if (debug)
          println("Unify " + c + " produces " + eq)
      un(eq).map{case (ts, os, ns) => (cMapWithDebug(c, ts, os, ns, debug), ts, os, ns)}
  }

  /*
   * This method factors all of the type equalities out of an inequality constraint
   * since they are better solved through unification than the algorithm in Dan Smith's
   * "Java Type Inference is Broken" paper.
   */

  private def getEquality(c: CFormula)(implicit ta: TypeAnalyzer): EFormula = reduce(c) match {
    case False => False
    case True => True
    case And(ts, os, ns) =>
      val teq = getCliques[Type, TPrimitive, _InferenceVarType](ts, 
          {case TPrimitive(pl,nl,pu,nu,pe,ne) => pl.filter(a => pu.exists(b => ta.equiv(a, b))) ++ pu.filter(a => pl.exists(b => ta.equiv(a, b)))})
      val oeq = getCliques[Op, OPrimitive, _InferenceVarOp](os,
          {case OPrimitive(ps, ns) => ps})
      val neq = getCliques[IntExpr, NPrimitive, _InferenceVarInt](ns,
          {case NPrimitive(ps, _) => ps})
      reduce(Conjuncts(teq, oeq, neq))
    case Or(cs) => 
      val eq = cs.map(getEquality)
      dis(eq)
  }

  private def getCliques[S,T, U <: S](xs: Map[U, T], makeClique: T => Set[S]): Set[Set[S]] = {
    xs.map{case (a, b) => makeClique(b) ++ Set(a)}.toSet
  }

  private def dis(eq: Set[EFormula])(implicit ta: TypeAnalyzer): EFormula = {
    if (eq.exists(isTrue(_)))
      True
    else
      reduce(Disjuncts(eq.filter(_.isInstanceOf[Conjuncts]).asInstanceOf[Set[Conjuncts]]))
  }

  private def dis(cs: Set[CFormula])(implicit ta: TypeAnalyzer): CFormula = {
    if(cs.exists(isTrue(_)))
      True
    else
      reduce(Or(cs.filter(_.isInstanceOf[And]).asInstanceOf[Set[And]]))
  }

  /*
   * This method should take an equality formula and produce
   * the principal unifier.
   */


  def unify(e: EFormula)(implicit ta: TypeAnalyzer): Option[(Type => Type, Op => Op, IntExpr => IntExpr)] =
    un(reduce(e))

  private def un(e: EFormula)(implicit ta: TypeAnalyzer): Option[(Type => Type, Op => Op, IntExpr => IntExpr)] = { // println("un of " + e)
   e match {
    case False => None
    case True => Some((tEmptySub, oEmptySub, nEmptySub))
    case e@Conjuncts(teq, oeq, neq) =>
      // Makes sure we don't have to use fixed point types
      def tError(x: (Set[_InferenceVarType], Set[Type])) = x match {
        case (a, b) => b.flatMap(TU.getInferenceVars).exists(a.contains(_))
      }
      // Takes a set of more than one inference variable and creates a substitution to unify them
      def tMake(x: Set[_InferenceVarType]) = tSubstitution({ val result = Map(x.tail.map((x.head, _)).toSeq:_*); // println("tMake subst = " + result);
                                                             result })
      val (mTSub, tSplit, tVars, tReg) = makeSub(teq, tError, tMake).getOrElse(return None)
      // No errors possible
      def oError(x: (Set[_InferenceVarOp], Set[Op])) = false
      def oMake(x: Set[_InferenceVarOp]) = oSubstitution(Map(x.tail.map((x.head, _)).toSeq:_*)) 
      val (mOSub, oSplit, oVars, oReg) = makeSub(oeq, oError, oMake).getOrElse(return None)
      // No errors possible for sizes either
      def nError(x: (Set[_InferenceVarInt], Set[IntExpr])) = false
      def nMake(x: Set[_InferenceVarInt]) = nSubstitution(Map(x.tail.map((x.head, _)).toSeq:_*))
      val (mNSub, nSplit, nVars, nReg) = makeSub(neq, nError, nMake).getOrElse(return None)
      // Combine op and type substitutions
      val mTOSub = (mTSub, mOSub) match {
        case (Some(tSub), Some(oSub)) => Some((insertOps(oSub) compose tSub, oSub))
        case (Some(tSub), None) => Some((tSub, oEmptySub))
        case (None, Some(oSub)) => Some((insertOps(oSub), oSub))
        case (None, None) => None
      }
      // and the size substitution with those
      val mTONSub = (mTOSub, mNSub) match {
        case (Some((tSub, oSub)), Some(nSub)) => Some((insertNats(nSub) compose tSub, oSub, nSub))
        case (Some((tSub, oSub)), None) => Some((tSub, oSub, nEmptySub))
        case (None, Some(nSub)) => Some((insertNats(nSub), oEmptySub, nSub))
        case (None, None) => None
      }
      mTONSub match{
        case Some((tSub, oSub, nSub)) =>
	  val eResult = eMap(e, tSub, oSub, nSub)
//	  println("un recursion 1: eMap produces " + eResult)
          // If there were any inference variables to be unified, then recurse
