      case (SAnyType(_), SAnyType(_)) => true
      case (SBottomType(_), SBottomType(_)) => true
      case (SVarType(_, nameL, _), SVarType(_, nameR, _)) =>
        equalIds(nameL, nameR)
      case (STraitSelfType(_, namedL, tysL),
