  /* Returns true if two FnHeaders are same. */
  private def equalFnHeaders(left: FnHeader, right: FnHeader,
                             ignoreAbstract: Boolean): Boolean = (left, right) match {
      case (SFnHeader(sparamsL, modsL, _, whereL, throwsL, contractL,
                      paramsL, retTyL),
