import java.nio.file.Path;
import java.util.*;
import jdk.jfr.consumer.*;

// java JfrAgg.java <file.jfr> <name>... : for each name, the ExecutionSample events with a
// frame whose "class.method" holds it (inclusive), and the top 15 self frames.
public class JfrAgg {
    public static void main(String[] a) throws Exception {
        List<String> names = Arrays.asList(a).subList(1, a.length);
        Map<String, Integer> incl = new LinkedHashMap<>();
        for (String n : names) incl.put(n, 0);
        Map<String, Integer> self = new HashMap<>();
        int total = 0;
        try (RecordingFile rf = new RecordingFile(Path.of(a[0]))) {
            while (rf.hasMoreEvents()) {
                RecordedEvent e = rf.readEvent();
                if (!e.getEventType().getName().equals("jdk.ExecutionSample")) continue;
                RecordedStackTrace st = e.getStackTrace();
                if (st == null) continue;
                total++;
                List<RecordedFrame> fs = st.getFrames();
                if (!fs.isEmpty()) {
                    RecordedMethod m = fs.get(0).getMethod();
                    String k = m.getType().getName() + "." + m.getName();
                    self.merge(k, 1, Integer::sum);
                }
                Set<String> seen = new HashSet<>();
                for (RecordedFrame f : fs) {
                    RecordedMethod m = f.getMethod();
                    String k = m.getType().getName() + "." + m.getName();
                    for (String n : names) if (k.contains(n) && seen.add(n)) incl.merge(n, 1, Integer::sum);
                }
            }
        }
        System.out.println("samples " + total);
        for (Map.Entry<String, Integer> en : incl.entrySet())
            System.out.printf("incl %-60s %7d %6.2f%%%n", en.getKey(), en.getValue(), 100.0 * en.getValue() / Math.max(1, total));
        self.entrySet().stream().sorted((x, y) -> y.getValue() - x.getValue()).limit(15)
            .forEach(en -> System.out.printf("self %-80s %7d %6.2f%%%n", en.getKey(), en.getValue(), 100.0 * en.getValue() / Math.max(1, total)));
    }
}

